import { ResponseError, UserError } from "../../errors.js";
import { Writer } from "../../protocol/writer.js";
import { createAPI } from "../definitions.js";
/*
  OffsetFetch Request (Version: 0) => group_id [topics]
    group_id => STRING
    topics => name [partition_indexes]
      name => STRING
      partition_indexes => INT32
*/
export function createRequest(groups, requireStable) {
    return createRequestForVersion(groups, requireStable, 0);
}
export function createRequestForVersion(groups, _requireStable, version) {
    const group = groups[0] ?? { groupId: '', topics: [] };
    if (group.topics == null) {
        throw new UserError(`OffsetFetch v${version} does not support fetching all offsets.`);
    }
    return Writer.create()
        .appendString(group.groupId, false)
        .appendArray(group.topics, (w, topic) => {
        w.appendString(topic.name, false).appendArray(topic.partitionIndexes, (w, partition) => w.appendInt32(partition), false, false);
    }, false, false);
}
/*
  OffsetFetch Response (Version: 0) => [topics]
    topics => name [partitions]
      name => STRING
      partitions => partition_index committed_offset metadata error_code
        partition_index => INT32
        committed_offset => INT64
        metadata => NULLABLE_STRING
        error_code => INT16
*/
export function parseResponse(_correlationId, apiKey, apiVersion, reader) {
    const errors = [];
    const response = {
        throttleTimeMs: 0,
        topics: reader.readArray((r, topicIndex) => ({
            name: r.readString(false),
            partitions: r.readArray((r, partitionIndex) => {
                const partition = {
                    partitionIndex: r.readInt32(),
                    committedOffset: r.readInt64(),
                    committedLeaderEpoch: -1,
                    metadata: r.readNullableString(false),
                    errorCode: r.readInt16()
                };
                if (partition.errorCode !== 0) {
                    errors.push([`/topics/${topicIndex}/partitions/${partitionIndex}`, [partition.errorCode, null]]);
                }
                return partition;
            }, false, false)
        }), false, false),
        errorCode: 0,
        groups: []
    };
    if (errors.length)
        throw new ResponseError(apiKey, apiVersion, Object.fromEntries(errors), response);
    return response;
}
export const api = createAPI(9, 0, createRequest, parseResponse, false, false);
